import React, { createContext, useContext, useEffect, useMemo, useState } from 'react';
import { Navigate, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom';
import { api, ApiError } from './lib/api';
import { calculateQuote } from '../shared/pricing';
import { formatUsd } from '../shared/money';
import type { AnalyticsResponse, AvailabilityDate, BookingDraft, Destination, OrderSummary, Quote, Tour } from '../shared/types';

type Mode='bot'|'tourist'|'manager'|'admin';

type AppCtx={
  booking:BookingDraft; setBooking:React.Dispatch<React.SetStateAction<BookingDraft>>;
  selectedTour:Tour|null; setSelectedTour:(t:Tour|null)=>void;
  latestOrder:OrderSummary|null; setLatestOrder:(o:OrderSummary|null)=>void;
  reloadToken:number; bump:()=>void;
};

const Context=createContext<AppCtx|null>(null);
const useApp=()=>{const c=useContext(Context);if(!c)throw new Error('Context');return c};

const defaultBooking:BookingDraft={
  tourId:'dalat-premium',format:'group',date:'2026-09-12',adults:2,children:[{height:112,age:null}],hotel:'Amiana Resort',transferZoneId:'north',
  participants:[{fullName:'',birthDate:''},{fullName:'',birthDate:''},{fullName:'',birthDate:''}],contact:{name:'',phone:'',telegram:''},paymentChoice:'deposit',paymentMethod:'card',source:'Telegram'
};

function useQuery(){return new URLSearchParams(useLocation().search)}

function modeFromPath(path:string):Mode{
  if(path.startsWith('/bot'))return'bot'; if(path.startsWith('/manager')||path.startsWith('/channels'))return'manager'; if(path.startsWith('/admin'))return'admin'; return'tourist';
}

export function App(){
  const [booking,setBooking]=useState<BookingDraft>(defaultBooking);
  const [selectedTour,setSelectedTour]=useState<Tour|null>(null);
  const [latestOrder,setLatestOrder]=useState<OrderSummary|null>(null);
  const [reloadToken,setReloadToken]=useState(0);
  const [ready,setReady]=useState(false);
  const [error,setError]=useState('');
  useEffect(()=>{api.session().then(()=>setReady(true)).catch(e=>{setError(e.message);setReady(true)})},[]);
  const value=useMemo(()=>({booking,setBooking,selectedTour,setSelectedTour,latestOrder,setLatestOrder,reloadToken,bump:()=>setReloadToken(x=>x+1)}),[booking,selectedTour,latestOrder,reloadToken]);
  if(!ready)return <FullState title="Запускаем MAX TOUR" text="Подключаем демо-сессию и данные."/>;
  if(error)return <FullState title="Не удалось открыть demo" text={error} action={()=>location.reload()} actionText="Повторить"/>;
  return <Context.Provider value={value}><ShellRoutes/></Context.Provider>;
}

function FullState({title,text,action,actionText}:{title:string;text:string;action?:()=>void;actionText?:string}){
  return <main className="full-state"><div className="loader-logo">M</div><h1>{title}</h1><p>{text}</p>{action&&<button className="btn primary" onClick={action}>{actionText}</button>}</main>
}

function ShellRoutes(){
  const location=useLocation(); const navigate=useNavigate(); const q=useQuery(); const clean=q.get('clean')==='1'; const mode=modeFromPath(location.pathname);
  const switchMode=(m:Mode)=>navigate(m==='bot'?'/bot':m==='manager'?'/manager':m==='admin'?'/admin':'/');
  return <div className={`app-shell ${clean?'clean':''}`}>
    {!clean&&<div className="role-switch demo-only">{([['bot','Бот'],['tourist','Турист'],['manager','Менеджер'],['admin','Админ']] as const).map(([m,label])=><button key={m} className={mode===m?'active':''} onClick={()=>switchMode(m)}>{label}</button>)}</div>}
    <Routes>
      <Route path="/bot" element={<BotPage/>}/>
      <Route path="/" element={<TouristFrame><HomePage/></TouristFrame>}/>
      <Route path="/catalog" element={<TouristFrame><CatalogPage/></TouristFrame>}/>
      <Route path="/tour/:id" element={<TouristFrame><TourDetailPage/></TouristFrame>}/>
      <Route path="/booking/date" element={<TouristFrame><BookingDatePage/></TouristFrame>}/>
      <Route path="/booking/participants" element={<TouristFrame><ParticipantsPage/></TouristFrame>}/>
      <Route path="/booking/hotel" element={<TouristFrame><HotelPage/></TouristFrame>}/>
      <Route path="/booking/travelers" element={<TouristFrame><TravelersPage/></TouristFrame>}/>
      <Route path="/booking/checkout" element={<TouristFrame><CheckoutPage/></TouristFrame>}/>
      <Route path="/booking/payment" element={<TouristFrame><PaymentPage/></TouristFrame>}/>
      <Route path="/booking/success" element={<TouristFrame><SuccessPage/></TouristFrame>}/>
      <Route path="/trips" element={<TouristFrame><TripsPage/></TouristFrame>}/>
      <Route path="/trips/:id" element={<TouristFrame><TripDetailPage/></TouristFrame>}/>
      <Route path="/help" element={<TouristFrame><HelpPage/></TouristFrame>}/>
      <Route path="/manager" element={<ManagerFrame><ManagerOrdersPage/></ManagerFrame>}/>
      <Route path="/manager/:id" element={<ManagerFrame><ManagerOrderPage/></ManagerFrame>}/>
      <Route path="/channels" element={<ManagerFrame><ChannelsPage/></ManagerFrame>}/>
      <Route path="/admin" element={<AdminFrame><AdminToursPage/></AdminFrame>}/>
      <Route path="/admin/tours/:id" element={<AdminFrame><AdminEditTourPage/></AdminFrame>}/>
      <Route path="/admin/add" element={<AdminFrame><AdminAddTourPage/></AdminFrame>}/>
      <Route path="/admin/schedule" element={<AdminFrame><AdminSchedulePage/></AdminFrame>}/>
      <Route path="/admin/analytics" element={<AdminFrame><AdminAnalyticsPage/></AdminFrame>}/>
      <Route path="/admin/directions" element={<AdminFrame><AdminDirectionsPage/></AdminFrame>}/>
      <Route path="*" element={<Navigate to="/" replace/>}/>
    </Routes>
  </div>
}

function BrandHeader({sub='Нячанг',back}:{sub?:string;back?:string}){const nav=useNavigate();return <header className="topbar"><button className="brand" onClick={()=>nav('/')}><b>MAX TOUR</b><small>{sub}</small></button>{back?<button className="icon-btn" onClick={()=>nav(back)}>←</button>:<button className="icon-btn" onClick={()=>nav('/help')}>?</button>}</header>}

function TouristFrame({children}:{children:React.ReactNode}){const nav=useNavigate();const path=useLocation().pathname;return <><main className="page tourist-page">{children}</main><nav className="bottom-nav">{[['/','⌂','Главная'],['/catalog','▦','Экскурсии'],['/trips','✦','Мои поездки'],['/help','?','Помощь']].map(([to,icon,label])=><button key={to} className={(to==='/'?path==='/':path.startsWith(to))?'active':''} onClick={()=>nav(to)}><span>{icon}</span>{label}</button>)}</nav></>}
function ManagerFrame({children}:{children:React.ReactNode}){const nav=useNavigate();return <main className="page wide"><BrandHeader sub="Manager demo"/><div className="toolbar"><button className="btn secondary small" onClick={()=>nav('/manager')}>Заказы</button><button className="btn secondary small" onClick={()=>nav('/channels')}>Каналы / Tilda</button></div>{children}</main>}
function AdminFrame({children}:{children:React.ReactNode}){const nav=useNavigate();const {bump}=useApp();const reset=async()=>{await api.reset();bump();nav('/')};return <main className="page wide"><BrandHeader sub="Admin / Director demo"/><div className="toolbar"><button className="btn secondary small" onClick={()=>nav('/admin')}>Экскурсии</button><button className="btn secondary small" onClick={()=>nav('/admin/schedule')}>Расписание / акции</button><button className="btn secondary small" onClick={()=>nav('/admin/analytics')}>Аналитика</button><button className="btn secondary small" onClick={()=>nav('/admin/directions')}>Направления</button><button className="btn danger small" onClick={reset}>Reset demo data</button></div>{children}</main>}

function ErrorBox({error}:{error:string}){return error?<div className="notice error">{error}</div>:null}
function DemoBadge({children='ДЕМО-ДАННЫЕ'}:{children?:React.ReactNode}){return <span className="badge demo-badge">{children}</span>}
function Price({minor}:{minor:number}){return <span className="price">{formatUsd(minor)}</span>}
function StepBar({step}:{step:number}){return <div className="steps">{[1,2,3,4,5,6].map(i=><i key={i} className={i<=step?'active':''}/>)}</div>}
function TourCard({tour}:{tour:Tour}){const nav=useNavigate();const price=tour.pricingRules.adultMinor??tour.pricingRules.adultFromMinor??0;return <article className="tour-card"><div className="tour-photo-wrap"><img src={tour.images[0]} alt={tour.title}/>{tour.promo?.enabled&&<div className="photo-badge">DEMO PROMO · {tour.promo.label||tour.promo.value}</div>}</div><div className="tour-card-body"><h3>{tour.title}</h3><div className="tags"><span>{tour.direction}</span><span>{tour.category}</span></div><div><Price minor={price}/>{tour.priceMode!=='fixed'&&<span className="muted"> от</span>}</div><button className="btn secondary block small" onClick={()=>nav(`/tour/${tour.id}`)}>Подробнее</button></div></article>}

function useTours(admin=false){const {reloadToken}=useApp();const [items,setItems]=useState<Tour[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const load=()=>{setLoading(true);(admin?api.adminTours():api.tours()).then(r=>setItems(r.items)).catch(e=>setError(e.message)).finally(()=>setLoading(false))};useEffect(load,[admin,reloadToken]);return{items,loading,error,reload:load}}
function HomePage(){
  const nav=useNavigate();const {items,loading,error}=useTours();const [destinations,setDestinations]=useState<Destination[]>([]);const [search,setSearch]=useState('');const [trips,setTrips]=useState<OrderSummary[]>([]);
  useEffect(()=>{api.destinations().then(r=>setDestinations(r.items));api.trips().then(r=>setTrips(r.items))},[]);
  const hero=items.find(t=>t.id==='dalat-premium')??items[0];
  return <><BrandHeader/><section className="hero-card"><div className="eyebrow">MAX TOUR Vietnam</div><div className="hero-number">Более 150</div><h1>экскурсий по всему Вьетнаму</h1><p>Выберите экскурсию, дату и участников, оформите поездку и пройдите DEMO-оплату прямо в Telegram.</p><div className="search-row"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Найти экскурсию"/><button onClick={()=>nav(`/catalog?q=${encodeURIComponent(search)}`)}>Найти</button></div>{hero&&<img src={hero.images[0]} alt="MAX TOUR Vietnam"/>}</section>
    <section className="section"><div className="eyebrow">Направления</div><div className="chips">{[...destinations.map(d=>d.name),'Премиум экскурсии'].map(x=><button key={x} onClick={()=>nav(`/catalog?filter=${encodeURIComponent(x)}`)}>{x}</button>)}</div></section>
    {trips[0]&&<section className="section"><h2>Ближайшая поездка</h2><div className="card"><span className="status success">{trips[0].status}</span><h3>{trips[0].tourTitle}</h3><p>{trips[0].selectedDate}</p><button className="btn secondary" onClick={()=>nav(`/trips/${trips[0].id}`)}>Открыть поездку</button></div></section>}
    <section className="section"><div className="section-head"><div><div className="eyebrow">Каталог</div><h2>Популярные экскурсии</h2></div><button className="btn secondary small" onClick={()=>nav('/catalog')}>Все</button></div><ErrorBox error={error}/>{loading?<div className="card">Загружаем экскурсии…</div>:<div className="tour-grid">{items.slice(0,4).map(t=><TourCard key={t.id} tour={t}/>)}</div>}</section></>
}

function CatalogPage(){
  const q=useQuery();const {items,loading,error}=useTours();const [search,setSearch]=useState(q.get('q')??'');const [filter,setFilter]=useState(q.get('filter')??'Все');
  const filters=['Все','Нячанг','Дананг','Фукуок','Муйне/Фантьет','Ханой','Премиум экскурсии'];
  const shown=items.filter(t=>(filter==='Все'||t.direction===filter||t.category===filter)&&(!search||t.title.toLowerCase().includes(search.toLowerCase())));
  return <><BrandHeader sub="Каталог"/><div className="eyebrow">T02</div><h1>Экскурсии</h1><input className="field-control" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Название экскурсии"/><div className="chips section-sm">{filters.map(f=><button key={f} className={filter===f?'active':''} onClick={()=>setFilter(f)}>{f}</button>)}</div><ErrorBox error={error}/>{loading?<div className="card section">Загрузка…</div>:shown.length?<div className="tour-grid section">{shown.map(t=><TourCard key={t.id} tour={t}/>)}</div>:<div className="card empty section">По выбранным условиям ничего не найдено.</div>}</>
}

function TourDetailPage(){
  const {id=''}=useParams();const nav=useNavigate();const {setBooking,setSelectedTour,reloadToken}=useApp();const [tour,setTour]=useState<Tour|null>(null);const [error,setError]=useState('');
  useEffect(()=>{api.tour(id).then(r=>{setTour(r.item);setSelectedTour(r.item);api.event('view_tour',r.item.id)}).catch(e=>setError(e.message))},[id,reloadToken]);
  if(error)return <><BrandHeader back="/catalog"/><ErrorBox error={error}/></>;if(!tour)return <><BrandHeader back="/catalog"/><div className="card">Загружаем экскурсию…</div></>;
  const start=()=>{setBooking(b=>({...b,tourId:tour.id,format:'group',date:'',participants:Array.from({length:b.adults+b.children.length},()=>({fullName:'',birthDate:''}))}));api.event('start_booking',tour.id);nav('/booking/date')};
  const adult=tour.pricingRules.adultMinor??tour.pricingRules.adultFromMinor??0;
  return <><BrandHeader sub={tour.direction} back="/catalog"/><div className="gallery">{tour.images.map((src,i)=><img key={i} src={src} alt={`${tour.title} — ${tour.program[i]??'локация'}`}/>)}</div><div className="eyebrow section-sm">{tour.category} · verifiedSite</div><h1>{tour.title}</h1>{tour.promo?.enabled&&<div className="notice warning"><b>DEMO PROMO:</b> {tour.promo.label} {tour.promo.value}</div>}<p>{tour.description}</p>
    <div className="info-grid section"><div className="card"><span className="caption">Сбор</span><b>{tour.pickup||'по программе'}</b></div><div className="card"><span className="caption">Возвращение</span><b>{tour.back||'по программе'}</b></div></div>
    <section className="section"><h2>Стоимость</h2><div className="card"><div><Price minor={adult}/>{tour.priceMode!=='fixed'&&<span className="muted"> от</span>}</div>{tour.pricingRules.childRules.map((r,i)=><p key={i}>{r.label}</p>)}{tour.pricingRules.privateTiers?.length?<><hr/><b>Индивидуальная экскурсия</b><div className="compact-list">{tour.pricingRules.privateTiers.map((p,i)=><span key={i}>{p.minPeople===p.maxPeople?`${p.minPeople} чел.`:`${p.minPeople}–${p.maxPeople} чел.`} — {formatUsd(p.totalMinor??(p.perPersonMinor??0)*p.minPeople)}{p.perPersonMinor?' / чел.':''}</span>)}</div></>:null}{tour.pricingRules.note&&<p className="muted">{tour.pricingRules.note}</p>}</div></section>
    {tour.requiredFields.includes('birthDate')&&<div className="notice section"><b>Для бронирования экскурсий в Далат:</b> ФИО и дата рождения всех участников.</div>}
    <section className="section"><h2>Программа</h2><div className="timeline">{tour.program.map((x,i)=><div className="timeline-item" key={x}><span>{i+1}</span><b>{x}</b></div>)}</div></section>
    <section className="section"><h2>Включено</h2><div className="card checklist">{tour.included.map(x=><div key={x}>✓ {x}</div>)}</div></section>
    {!!tour.extraCosts.length&&<section className="section"><h2>Дополнительные расходы</h2><div className="card checklist">{tour.extraCosts.map(x=><div key={x}>{x}</div>)}<p className="caption">Расходы на месте по желанию не добавляются автоматически к booking total.</p></div></section>}
    <section className="section"><h2>Что взять</h2><div className="card checklist">{tour.whatToTake.map(x=><div key={x}>{x}</div>)}</div></section>
    <CancellationBlock/>
    <div className="sticky-cta"><button className="btn accent block" onClick={start}>Выбрать дату</button></div></>
}

function CancellationBlock(){return <section className="section"><h2>Отмена и перенос</h2><div className="card"><p><b>Перенос:</b> бесплатно до 17:00 за день до экскурсии; после этого удерживается 30%.</p><p><b>Отмена:</b> бесплатно более чем за 48 часов; до 17:00 за день до выезда — удержание 30%; в день выезда или при неявке — удержание 100%.</p><p><b>Возврат:</b> до 7 рабочих дней; возможны банковские комиссии.</p></div></section>}
function useCurrentTour(){const {booking,selectedTour,setSelectedTour,reloadToken}=useApp();const [tour,setTour]=useState<Tour|null>(selectedTour?.id===booking.tourId?selectedTour:null);const [error,setError]=useState('');useEffect(()=>{setError('');api.tour(booking.tourId).then(r=>{setTour(r.item);setSelectedTour(r.item)}).catch(e=>setError(e.message))},[booking.tourId,reloadToken]);return{tour,error}}
function LocalTotals({tour,booking}:{tour:Tour;booking:BookingDraft}){const q=calculateQuote(tour,booking,30);return <div className="total-card">{q.lines.map((x,i)=><div className="total-line" key={i}><span>{x.label}</span><b>{formatUsd(x.amountMinor)}</b></div>)}<div className="total-line"><span>Доп. трансфер</span><b>{formatUsd(q.transferMinor)}</b></div><div className="total-line grand"><span>Итого</span><b>{formatUsd(q.totalMinor)}</b></div></div>}

function BookingDatePage(){const nav=useNavigate();const {booking,setBooking}=useApp();const {tour,error}=useCurrentTour();const [dates,setDates]=useState<AvailabilityDate[]>([]);useEffect(()=>{if(tour)api.availability(tour.id).then(r=>setDates(r.items))},[tour?.id]);if(!tour)return <><BrandHeader back="/catalog"/><ErrorBox error={error}/></>;
  return <><BrandHeader sub="Бронирование" back={`/tour/${tour.id}`}/><StepBar step={1}/><h1>Дата и формат</h1><div className="segmented"><button className={booking.format==='group'?'active':''} onClick={()=>setBooking(b=>({...b,format:'group'}))}>Групповая</button><button className={booking.format==='private'?'active':''} onClick={()=>setBooking(b=>({...b,format:'private'}))}>Индивидуальная</button></div><div className="notice demo section-sm"><b>DEMO AVAILABILITY.</b> Даты ниже показывают механику интерфейса и не являются заявлением о реальном наличии мест.</div><div className="date-grid section">{dates.length?dates.map(d=><button key={d.date} className={`date-card ${booking.date===d.date?'selected':''}`} onClick={()=>setBooking(b=>({...b,date:d.date}))}><b>{d.date}</b><span className={`status ${d.status==='available'?'success':d.status==='low'?'warning':''}`}>{d.label}</span></button>):<button className={`date-card ${booking.date==='DEMO-REQUEST'?'selected':''}`} onClick={()=>setBooking(b=>({...b,date:'DEMO-REQUEST'}))}><b>Дата по запросу</b><span className="status warning">по запросу</span></button>}</div><div className="sticky-cta"><button className="btn accent block" disabled={!booking.date&&dates.length>0} onClick={()=>nav('/booking/participants')}>Продолжить</button></div></>
}

function ParticipantsPage(){const nav=useNavigate();const {booking,setBooking}=useApp();const {tour,error}=useCurrentTour();if(!tour)return <><BrandHeader back="/booking/date"/><ErrorBox error={error}/></>;
  const setAdults=(n:number)=>setBooking(b=>{const adults=Math.max(1,n);const count=adults+b.children.length;const participants=Array.from({length:count},(_,i)=>b.participants[i]??{fullName:'',birthDate:''});return{...b,adults,participants}});
  const setChildren=(n:number)=>setBooking(b=>{const len=Math.max(0,n);const children=Array.from({length:len},(_,i)=>b.children[i]??{height:112,age:null});const participants=Array.from({length:b.adults+len},(_,i)=>b.participants[i]??{fullName:'',birthDate:''});return{...b,children,participants}});
  const needsHeight=tour.pricingRules.childRules.some(r=>r.type==='height'); const needsAge=tour.pricingRules.childRules.some(r=>r.type==='age');
  return <><BrandHeader sub="Бронирование" back="/booking/date"/><StepBar step={2}/><h1>Участники</h1><CounterCard label="Взрослые" value={booking.adults} onMinus={()=>setAdults(booking.adults-1)} onPlus={()=>setAdults(booking.adults+1)}/><CounterCard label="Дети" value={booking.children.length} onMinus={()=>setChildren(booking.children.length-1)} onPlus={()=>setChildren(booking.children.length+1)}/>
    {booking.children.map((c,i)=><div className="card" key={i}><h3>Ребёнок {i+1}</h3>{needsHeight&&<label className="field-label">Рост, см<input className="field-control" type="number" value={c.height??''} onChange={e=>setBooking(b=>({...b,children:b.children.map((x,j)=>j===i?{...x,height:Number(e.target.value)}:x)}))}/></label>}{needsAge&&<label className="field-label">Возраст, лет<input className="field-control" type="number" value={c.age??''} onChange={e=>setBooking(b=>({...b,children:b.children.map((x,j)=>j===i?{...x,age:Number(e.target.value)}:x)}))}/></label>}<p className="caption">Тариф ребёнка рассчитывается по правилам именно этой экскурсии.</p></div>)}
    <section className="section"><LocalTotals tour={tour} booking={booking}/></section><div className="sticky-cta"><button className="btn accent block" onClick={()=>nav('/booking/hotel')}>Продолжить</button></div></>
}
function CounterCard({label,value,onMinus,onPlus}:{label:string;value:number;onMinus:()=>void;onPlus:()=>void}){return <div className="card counter-card"><div><b>{label}</b><span className="caption">Тариф конкретного тура</span></div><div className="counter"><button onClick={onMinus}>−</button><b>{value}</b><button onClick={onPlus}>+</button></div></div>}

function HotelPage(){const nav=useNavigate();const {booking,setBooking}=useApp();const {tour,error}=useCurrentTour();if(!tour)return <><BrandHeader back="/booking/participants"/><ErrorBox error={error}/></>;const local=calculateQuote(tour,booking,30);
  const setHotel=(hotel:string,zone?:string)=>setBooking(b=>({...b,hotel,transferZoneId:zone}));
  return <><BrandHeader sub="Бронирование" back="/booking/participants"/><StepBar step={3}/><h1>Отель и трансфер</h1><label className="field-label">Название отеля<input className="field-control" value={booking.hotel} onChange={e=>setBooking(b=>({...b,hotel:e.target.value,transferZoneId:undefined}))}/></label><div className="chips"><button onClick={()=>setHotel('Amiana Resort','north')}>Amiana Resort</button><button onClick={()=>setHotel('Nha Trang center','center')}>Центр</button><button onClick={()=>setHotel('Cam Ranh','camranh')}>Камрань</button></div><div className="card section"><span className="caption">Зона трансфера</span><h3>{local.transferLabel}</h3><Price minor={local.transferMinor}/><p>Дополнительный трансфер из отдалённого района · {booking.adults+booking.children.length} путешественников.</p></div><div className="notice">MAX TOUR указывает, что большинство экскурсий включает основные услуги; дополнительный трансфер нужен при проживании в удалённых районах.</div><section className="section"><LocalTotals tour={tour} booking={booking}/></section><div className="sticky-cta"><button className="btn accent block" onClick={()=>nav('/booking/travelers')}>Продолжить</button></div></>
}

function TravelersPage(){const nav=useNavigate();const {booking,setBooking}=useApp();const {tour,error}=useCurrentTour();const [validation,setValidation]=useState('');if(!tour)return <><BrandHeader back="/booking/hotel"/><ErrorBox error={error}/></>;
  const updateParticipant=(i:number,key:'fullName'|'birthDate'|'passport',value:string)=>setBooking(b=>({...b,participants:b.participants.map((p,j)=>j===i?{...p,[key]:value}:p)}));
  const proceed=()=>{const people=booking.adults+booking.children.length;const ok=booking.participants.length===people&&booking.participants.every(p=>(!tour.requiredFields.includes('fullName')||p.fullName.trim())&&(!tour.requiredFields.includes('birthDate')||p.birthDate)&&(!tour.requiredFields.includes('passport')||p.passport))&&booking.contact.name.trim()&&booking.contact.phone.trim();if(!ok){setValidation('Заполните обязательные поля всех участников и основной контакт.');return}nav('/booking/checkout')};
  return <><BrandHeader sub="Бронирование" back="/booking/hotel"/><StepBar step={4}/><h1>Данные туристов</h1><div className="notice demo">Требования конкретной экскурсии берутся из её verified data. Контактные поля ниже — поля будущей системы для самостоятельного заказа.</div><section className="section form-stack">{booking.participants.map((p,i)=><div className="card" key={i}><h3>Участник {i+1}</h3><label className="field-label">ФИО<input className="field-control" value={p.fullName} onChange={e=>updateParticipant(i,'fullName',e.target.value)}/></label>{tour.requiredFields.includes('birthDate')&&<label className="field-label">Дата рождения<input className="field-control" type="date" value={p.birthDate??''} onChange={e=>updateParticipant(i,'birthDate',e.target.value)}/></label>}{tour.requiredFields.includes('passport')&&<label className="field-label">Паспорт<input className="field-control" value={p.passport??''} onChange={e=>updateParticipant(i,'passport',e.target.value)}/></label>}</div>)}</section><section className="section"><h2>Основной контакт</h2><div className="card form-stack"><label className="field-label">Имя<input className="field-control" value={booking.contact.name} onChange={e=>setBooking(b=>({...b,contact:{...b.contact,name:e.target.value}}))}/></label><label className="field-label">Телефон<input className="field-control" value={booking.contact.phone} onChange={e=>setBooking(b=>({...b,contact:{...b.contact,phone:e.target.value}}))}/></label><label className="field-label">Telegram / контакт<input className="field-control" value={booking.contact.telegram??''} onChange={e=>setBooking(b=>({...b,contact:{...b.contact,telegram:e.target.value}}))}/></label></div></section><ErrorBox error={validation}/><div className="sticky-cta"><button className="btn accent block" onClick={proceed}>Проверить и продолжить</button></div></>
}

function CheckoutPage(){const nav=useNavigate();const {booking,setBooking}=useApp();const {tour,error}=useCurrentTour();const [quote,setQuote]=useState<Quote|null>(null);const [serverError,setServerError]=useState('');useEffect(()=>{if(tour)api.quote(booking).then(r=>setQuote(r.quote)).catch(e=>setServerError(e.message))},[tour?.id,booking]);if(!tour)return <><BrandHeader back="/booking/travelers"/><ErrorBox error={error}/></>;
  return <><BrandHeader sub="Бронирование" back="/booking/travelers"/><StepBar step={5}/><h1>Проверка заказа</h1><div className="card"><h3>{tour.title}</h3><p>{booking.date||'DEMO date по запросу'}</p><p>{booking.adults} взрослых{booking.children.length?`, ${booking.children.length} ребёнок/детей`:''}{booking.children.some(c=>c.height)?` · ${booking.children.map(c=>c.height?`${c.height} см`:null).filter(Boolean).join(', ')}`:''}</p><p>{booking.hotel}</p></div><ErrorBox error={serverError}/>{quote?<section className="section"><QuoteTotals quote={quote}/></section>:<div className="card section">Сервер пересчитывает итоговую сумму…</div>}<section className="section"><h2>Сколько оплатить сейчас</h2><div className="segmented"><button className={booking.paymentChoice==='deposit'?'active':''} onClick={()=>setBooking(b=>({...b,paymentChoice:'deposit'}))}>Предоплата</button><button className={booking.paymentChoice==='full'?'active':''} onClick={()=>setBooking(b=>({...b,paymentChoice:'full'}))}>Полная оплата</button></div><div className="card section-sm"><Price minor={quote?.payNowMinor??0}/><p>{booking.paymentChoice==='deposit'?'DEMO CONFIGURATION = 30%':'100% стоимости'}</p><div className="notice demo">Размер предоплаты задаётся для тура. В демо используется 30%; это не утверждение о фиксированном депозите Dalat Premium.</div></div></section><div className="sticky-cta"><button className="btn accent block" disabled={!quote} onClick={()=>nav('/booking/payment')}>К выбору оплаты</button></div></>
}
function QuoteTotals({quote}:{quote:Quote}){return <div className="total-card">{quote.lines.map((x,i)=><div className="total-line" key={i}><span>{x.label}</span><b>{formatUsd(x.amountMinor)}</b></div>)}<div className="total-line"><span>Экскурсия</span><b>{formatUsd(quote.tourSubtotalMinor)}</b></div><div className="total-line"><span>Доп. трансфер</span><b>{formatUsd(quote.transferMinor)}</b></div><div className="total-line grand"><span>Итого</span><b>{formatUsd(quote.totalMinor)}</b></div></div>}

function PaymentPage(){
  const nav=useNavigate();const {booking,setBooking,setLatestOrder}=useApp();const {tour,error}=useCurrentTour();const [quote,setQuote]=useState<Quote|null>(null);const [busy,setBusy]=useState(false);const [serverError,setServerError]=useState('');const [orderKey]=useState(()=>crypto.randomUUID());const [paymentKey]=useState(()=>crypto.randomUUID());
  useEffect(()=>{if(tour)api.quote(booking).then(r=>setQuote(r.quote)).catch(e=>setServerError(e.message))},[tour?.id,booking]);
  if(!tour)return <><BrandHeader back="/booking/checkout"/><ErrorBox error={error}/></>;
  const methods:[BookingDraft['paymentMethod'],string,string][]=[['card','Банковская карта','Опубликованный MAX TOUR способ; автоматизация не заявлена'],['sbp','СБП / Kaspi','Опубликованный MAX TOUR способ; платёжный провайдер не выбран'],['transfer','Банковский / международный перевод','Опубликованный MAX TOUR способ'],['cash','Наличными','Текущий способ MAX TOUR; не автоматизирован в demo']];
  const pay=async()=>{if(busy||!quote||booking.paymentMethod==='cash')return;setBusy(true);setServerError('');try{const created=await api.createOrder(booking,orderKey);const paid=await api.pay(created.order.id,paymentKey);setLatestOrder(paid.order);nav('/booking/success')}catch(e){setServerError(e instanceof Error?e.message:'Ошибка DEMO-оплаты')}finally{setBusy(false)}};
  return <><BrandHeader sub="Оплата" back="/booking/checkout"/><StepBar step={6}/><h1>Выберите способ оплаты</h1><div className="notice demo"><b>ДЕМО — реальное списание не выполняется.</b> Платёжный провайдер, merchant account и комиссии не выбраны.</div>
    <section className="section"><div className="eyebrow">Оплатить онлайн</div>{methods.slice(0,3).map(([id,label,desc])=><button className={`payment-method ${booking.paymentMethod===id?'selected':''}`} key={id} onClick={()=>setBooking(b=>({...b,paymentMethod:id}))}><span><b>{label}</b><small>{desc}</small></span><i>{booking.paymentMethod===id?'✓':''}</i></button>)}</section>
    <section className="section"><div className="eyebrow">Другой текущий способ MAX TOUR</div>{methods.slice(3).map(([id,label,desc])=><button className={`payment-method ${booking.paymentMethod===id?'selected':''}`} key={id} onClick={()=>setBooking(b=>({...b,paymentMethod:id}))}><span><b>{label}</b><small>{desc}</small></span><i>{booking.paymentMethod===id?'✓':''}</i></button>)}</section>
    {booking.paymentMethod==='cash'&&<div className="notice section">Наличные показаны как текущий способ MAX TOUR, но автоматическая online-оплата для него в demo не выполняется. Выберите online-способ для прохождения DEMO payment flow.</div>}<ErrorBox error={serverError}/><div className="card section pay-now"><span className="caption">К оплате сейчас</span><Price minor={quote?.payNowMinor??0}/></div><div className="sticky-cta"><button className="btn accent block" disabled={!quote||busy||booking.paymentMethod==='cash'} onClick={pay}>{busy?'Создаём DEMO-заказ…':`Оплатить ${formatUsd(quote?.payNowMinor??0)} — DEMO`}</button></div></>
}

function SuccessPage(){const nav=useNavigate();const {latestOrder}=useApp();const [order,setOrder]=useState<OrderSummary|null>(latestOrder);useEffect(()=>{if(!order)api.trips().then(r=>setOrder(r.items[0]??null))},[order]);if(!order)return <><BrandHeader sub="Готово"/><div className="card empty"><h2>Заказ пока не создан</h2><button className="btn accent" onClick={()=>nav('/catalog')}>Выбрать экскурсию</button></div></>;
  return <><BrandHeader sub="Готово"/><div className="success-card"><div className="success-icon">✓</div><span className="status success">Бронирование оформлено</span><h1>{order.id}</h1><p>{order.paymentState}</p></div><div className="card section"><h3>{order.tourTitle}</h3><p>{order.selectedDate}</p><InfoLine label="Итого" value={formatUsd(order.totalMinor)}/><InfoLine label="Оплачено" value={formatUsd(order.paidMinor)}/><InfoLine label="Остаток" value={formatUsd(order.remainingMinor)}/></div><div className="notice section">Этот заказ уже сохранён в D1 текущей demo-сессии и доступен менеджеру. Внешняя отправка через Telegram Bot API остаётся simulated, если bot credentials не настроены.</div><div className="button-row section"><button className="btn accent" onClick={()=>nav(`/trips/${order.id}`)}>Открыть поездку</button><button className="btn secondary" onClick={()=>nav(`/manager/${order.id}`)}>Показать менеджеру</button></div></>
}

function TripsPage(){const nav=useNavigate();const {reloadToken}=useApp();const [items,setItems]=useState<OrderSummary[]>([]);const [error,setError]=useState('');useEffect(()=>{api.trips().then(r=>setItems(r.items)).catch(e=>setError(e.message))},[reloadToken]);return <><BrandHeader sub="Мои поездки"/><div className="eyebrow">T11</div><h1>Мои поездки</h1><ErrorBox error={error}/>{items.length?<div className="stack">{items.map(o=><div className="card" key={o.id}><span className="status success">{o.status}</span><h3>{o.tourTitle}</h3><p>{o.selectedDate}</p><InfoLine label="Оплачено" value={formatUsd(o.paidMinor)}/><InfoLine label="Остаток" value={formatUsd(o.remainingMinor)}/><button className="btn secondary block" onClick={()=>nav(`/trips/${o.id}`)}>Открыть поездку</button></div>)}</div>:<div className="card empty"><h3>Пока нет оформленных поездок</h3><p>Пройдите путь бронирования — поездка сохранится в D1.</p><button className="btn accent" onClick={()=>nav('/tour/dalat-premium')}>Выбрать экскурсию</button></div>}</>}

function TripDetailPage(){const {id=''}=useParams();const [order,setOrder]=useState<OrderSummary|null>(null);const [tour,setTour]=useState<Tour|null>(null);const [error,setError]=useState('');useEffect(()=>{api.order(id).then(async r=>{setOrder(r.order);const tr=await api.tour(r.order.tourId);setTour(tr.item)}).catch(e=>setError(e.message))},[id]);return <><BrandHeader sub="Поездка" back="/trips"/><div className="eyebrow">T12</div><ErrorBox error={error}/>{order&&tour?<><h1>{order.tourTitle}</h1><div className="card"><InfoLine label="Дата" value={order.selectedDate}/><InfoLine label="Сбор" value={tour.pickup||'По программе тура'}/><InfoLine label="Участники" value={order.participantsSummary}/>{order.children?.map((c,i)=><InfoLine key={i} label={`Ребёнок ${i+1}`} value={`${c.height!=null?`${c.height} см`:c.age!=null?`${c.age} лет`:'тариф по правилам тура'}`}/>) }<InfoLine label="Отель" value={order.hotel}/><InfoLine label="Трансфер" value={formatUsd(order.transferMinor)}/><InfoLine label="Итого" value={formatUsd(order.totalMinor)}/><InfoLine label="Оплачено" value={formatUsd(order.paidMinor)}/><InfoLine label="Остаток" value={formatUsd(order.remainingMinor)}/><InfoLine label="Статус" value={order.status}/></div><CancellationBlock/><section className="section"><button className="btn secondary block" onClick={()=>alert('DEMO: сообщение менеджеру не отправляется.')}>Связаться с поддержкой</button></section></>:<div className="card">Загружаем поездку…</div>}</>}

function HelpPage(){return <><BrandHeader sub="Помощь"/><h1>Помощь</h1><div className="card"><h3>Связаться с MAX TOUR</h3><p>WhatsApp · Telegram · MAX</p><div className="notice demo">DEMO: внешний transport сообщения не выполняется.</div></div><section className="section"><h2>Что уже можно сделать здесь</h2><ul className="clean-list"><li>Выбрать экскурсию и дату</li><li>Рассчитать участников и трансфер</li><li>Оформить DEMO-заказ и оплату</li><li>Открыть поездку и её статус</li></ul></section></>}

function BotPage(){const nav=useNavigate();const [trip,setTrip]=useState<OrderSummary|null>(null);useEffect(()=>{api.trips().then(r=>setTrip(r.items[0]??null))},[]);return <main className="page bot-page"><div className="telegram-window"><div className="telegram-head"><div className="avatar">M</div><div><b>MAX TOUR</b><small>bot · simulated interaction</small></div></div><div className="telegram-chat"><div className="bubble"><b>Здравствуйте!</b><p>Подберём экскурсию по Вьетнаму и поможем оформить поездку прямо в Telegram.</p><div className="bot-buttons"><button onClick={()=>nav('/catalog')}>Открыть экскурсии</button><button onClick={()=>nav('/trips')}>Мои поездки</button><button onClick={()=>alert('DEMO: открывается контакт с менеджером, отправка не выполняется.')}>Связаться с менеджером</button></div></div>{trip&&<div className="bubble"><b>Бронирование {trip.id} оформлено</b><p>{trip.tourTitle}</p><small>simulated bot confirmation</small><div className="bot-buttons"><button onClick={()=>nav(`/trips/${trip.id}`)}>Открыть поездку</button></div></div>}</div></div></main>}

function ManagerOrdersPage(){const nav=useNavigate();const {reloadToken}=useApp();const [items,setItems]=useState<OrderSummary[]>([]);const [filter,setFilter]=useState('Все');const [error,setError]=useState('');useEffect(()=>{api.managerOrders().then(r=>setItems(r.items)).catch(e=>setError(e.message))},[reloadToken]);const shown=items.filter(o=>filter==='Все'||filter==='Новые'&&o.status==='Новый'||filter==='Оплачено'&&o.paidMinor>0||filter==='Подтверждено'&&o.status==='Подтверждено');return <><div className="section-head"><div><div className="eyebrow">M01</div><h1>Заказы</h1></div><DemoBadge>DEMO ORDERS</DemoBadge></div><div className="chips">{['Все','Новые','Оплачено','Подтверждено'].map(x=><button className={filter===x?'active':''} key={x} onClick={()=>setFilter(x)}>{x}</button>)}</div><ErrorBox error={error}/><div className="stack section">{shown.map(o=><div className="card order-card" key={o.id}><div className="section-head"><div><span className={`status ${o.paidMinor?'success':''}`}>{o.paymentState}</span><h3>{o.tourTitle}</h3></div><Price minor={o.totalMinor}/></div><p>{o.selectedDate} · {o.customer}</p><div className="tags"><span>{o.source}</span><span>{o.status}</span></div><button className="btn secondary block" onClick={()=>nav(`/manager/${o.id}`)}>Открыть заказ</button></div>)}</div></>}

function ManagerOrderPage(){const {id=''}=useParams();const [order,setOrder]=useState<OrderSummary|null>(null);const [error,setError]=useState('');const [message,setMessage]=useState('');const load=()=>api.managerOrder(id).then(r=>setOrder(r.order)).catch(e=>setError(e.message));useEffect(load,[id]);const setStatus=async(status:OrderSummary['status'])=>{try{const r=await api.managerStatus(id,status);setOrder(r.order);setMessage('Статус сохранён в D1 и сохраняется после перезагрузки.')}catch(e){setError(e instanceof Error?e.message:'Ошибка')}};return <><button className="btn secondary small" onClick={()=>history.back()}>← Заказы</button><div className="eyebrow section">M02</div><h1>{id}</h1><ErrorBox error={error}/>{order?<><div className="grid two"><div className="card"><h3>{order.tourTitle}</h3><InfoLine label="Дата" value={order.selectedDate}/><InfoLine label="Участники" value={order.participantsSummary}/><InfoLine label="Отель" value={order.hotel}/><InfoLine label="Трансфер" value={formatUsd(order.transferMinor)}/></div><div className="card"><InfoLine label="Source" value={order.source}/><InfoLine label="Клиент" value={order.customer}/><InfoLine label="Контакт" value={order.contact}/><InfoLine label="Итого" value={formatUsd(order.totalMinor)}/><InfoLine label="Оплачено" value={formatUsd(order.paidMinor)}/><InfoLine label="Остаток" value={formatUsd(order.remainingMinor)}/></div></div><section className="card section"><h3>Статус</h3><div className="button-row"><button className="btn accent" onClick={()=>setStatus('Подтверждено')}>Подтвердить</button><select className="field-control inline" value={order.status} onChange={e=>setStatus(e.target.value as OrderSummary['status'])}><option>Новый</option><option>Оплачено</option><option>Подтверждено</option></select><button className="btn secondary" onClick={()=>setMessage('DEMO: контакт доступен менеджеру, внешнее сообщение не отправлено.')}>Связаться</button></div>{message&&<div className="notice success section-sm">{message}</div>}</section></>:<div className="card">Загружаем заказ…</div>}</>}

function ChannelsPage(){const [items,setItems]=useState<OrderSummary[]>([]);useEffect(()=>{api.managerOrders().then(r=>setItems(r.items))},[]);const tg=items.find(o=>o.source==='Telegram'),site=items.find(o=>o.source==='Сайт');return <><div className="eyebrow">C01 · Схема будущей интеграции</div><h1>Сайт и Telegram — два канала одной системы</h1><div className="notice demo">Tilda API и production sync здесь не заявлены как уже подключённые. Экран показывает целевую архитектуру будущей системы.</div><section className="integration section"><div className="integration-node"><b>Сайт MAX TOUR</b><small>Tilda</small></div><div className="arrow">→</div><div className="integration-node core"><b>Единая система бронирований</b><small>одинаковая структура заказа</small></div><div className="arrow">→</div><div className="integration-node"><b>Заказы менеджеру</b></div></section><section className="section"><h2>Одинаковая структура заказа</h2><div className="grid two">{[tg,site].filter(Boolean).map(o=><div className="card" key={o!.id}><span className="tag">{o!.source}</span><h3>{o!.id}</h3><p>{o!.tourTitle}</p><InfoLine label="Статус" value={o!.status}/><InfoLine label="Оплата" value={o!.paymentState}/></div>)}</div></section><section className="integration section compact"><div className="integration-node"><b>Telegram Mini App</b></div><div className="arrow">→</div><div className="integration-node core"><b>source → tour → order → payment</b></div><div className="arrow">→</div><div className="integration-node"><b>Analytics</b></div></section></>}

function AdminToursPage(){const nav=useNavigate();const {bump}=useApp();const {items,error,reload}=useTours(true);const mutate=async(t:Tour,patch:any)=>{await api.patchTour(t.id,patch);bump();reload()};const duplicate=async(t:Tour)=>{await api.addTour({direction:t.direction,title:`Копия — ${t.title}`,description:t.description,priceMode:t.priceMode,adultMinor:t.pricingRules.adultMinor??t.pricingRules.adultFromMinor??0,scheduleMode:t.scheduleMode,images:t.images,published:false});bump();reload()};return <><div className="section-head"><div><div className="eyebrow">A01</div><h1>Экскурсии</h1></div><button className="btn accent" onClick={()=>nav('/admin/add')}>Добавить экскурсию</button></div><ErrorBox error={error}/><div className="tour-grid">{items.map(t=><div className="card" key={t.id}><div className="tags"><span>{t.direction}</span><span className={`status ${t.published?'success':'warning'}`}>{t.published?'Опубликовано':'Снято'}</span>{t.dataStatus==='userCreatedDemo'&&<DemoBadge>userCreatedDemo</DemoBadge>}</div><h3>{t.title}</h3><p className="muted">{t.description}</p><Price minor={t.pricingRules.adultMinor??t.pricingRules.adultFromMinor??0}/><div className="button-row section-sm"><button className="btn secondary small" onClick={()=>nav(`/admin/tours/${t.id}`)}>Редактировать</button><button className="btn secondary small" onClick={()=>duplicate(t)}>Дублировать</button><button className="btn secondary small" onClick={()=>mutate(t,{published:!t.published})}>{t.published?'Снять':'Опубликовать'}</button></div></div>)}</div></>}

function AdminEditTourPage(){const {id=''}=useParams();const nav=useNavigate();const {bump}=useApp();const [tour,setTour]=useState<Tour|null>(null);const [title,setTitle]=useState('');const [description,setDescription]=useState('');const [adult,setAdult]=useState(0);const [program,setProgram]=useState('');const [included,setIncluded]=useState('');const [extra,setExtra]=useState('');const [images,setImages]=useState('');const [published,setPublished]=useState(true);const [message,setMessage]=useState('');const [error,setError]=useState('');useEffect(()=>{api.tour(id).then(r=>{const t=r.item;setTour(t);setTitle(t.title);setDescription(t.description);setAdult((t.pricingRules.adultMinor??t.pricingRules.adultFromMinor??0)/100);setProgram(t.program.join('\n'));setIncluded(t.included.join('\n'));setExtra(t.extraCosts.join('\n'));setImages(t.images.join('\n'));setPublished(t.published)}).catch(e=>setError(e.message))},[id]);const save=async()=>{try{const r=await api.patchTour(id,{title,description,adultMinor:Math.round(adult*100),published,program:lines(program),included:lines(included),extraCosts:lines(extra),images:lines(images)});setTour(r.item);setMessage('Сохранено в D1 как override текущей demo-сессии. Tourist detail и server quote читают обновлённые данные.');bump()}catch(e){setError(e instanceof Error?e.message:'Ошибка сохранения')}};if(!tour)return <><ErrorBox error={error}/><div className="card">Загружаем тур…</div></>;return <><button className="btn secondary small" onClick={()=>nav('/admin')}>← Экскурсии</button><div className="eyebrow section">A02</div><h1>Редактировать тур</h1><div className="grid two"><div className="form-stack"><label className="field-label">Название<input className="field-control" value={title} onChange={e=>setTitle(e.target.value)}/></label><label className="field-label">Описание<textarea className="field-control" value={description} onChange={e=>setDescription(e.target.value)}/></label><label className="field-label">Adult price, $<input className="field-control" type="number" value={adult} onChange={e=>setAdult(Number(e.target.value))}/></label><label className="checkbox"><input type="checkbox" checked={published} onChange={e=>setPublished(e.target.checked)}/> Опубликовано</label></div><div className="form-stack"><label className="field-label">Программа<textarea className="field-control tall" value={program} onChange={e=>setProgram(e.target.value)}/></label><label className="field-label">Включено<textarea className="field-control" value={included} onChange={e=>setIncluded(e.target.value)}/></label><label className="field-label">Дополнительные расходы<textarea className="field-control" value={extra} onChange={e=>setExtra(e.target.value)}/></label><label className="field-label">Images, по одному URL на строку<textarea className="field-control" value={images} onChange={e=>setImages(e.target.value)}/></label></div></div><button className="btn accent section" onClick={save}>Сохранить изменения</button><ErrorBox error={error}/>{message&&<div className="notice success section-sm">{message}</div>}</>}

function AdminAddTourPage(){const nav=useNavigate();const {bump}=useApp();const [directions,setDirections]=useState<Destination[]>([]);const [form,setForm]=useState({direction:'Нячанг',title:'',description:'',priceMode:'fixed' as Tour['priceMode'],adult:'50',scheduleMode:'demoDates' as Tour['scheduleMode'],image:'',published:true});const [error,setError]=useState('');useEffect(()=>{api.directions().then(r=>setDirections(r.items))},[]);const save=async()=>{try{await api.addTour({direction:form.direction,title:form.title,description:form.description,priceMode:form.priceMode,adultMinor:Math.round(Number(form.adult)*100),scheduleMode:form.scheduleMode,images:form.image?[form.image]:[],published:form.published});bump();nav('/admin')}catch(e){setError(e instanceof Error?e.message:'Ошибка')}};return <><button className="btn secondary small" onClick={()=>nav('/admin')}>← Экскурсии</button><div className="eyebrow section">A03 · user-created demo</div><h1>Добавить экскурсию</h1><div className="grid two"><label className="field-label">Направление<select className="field-control" value={form.direction} onChange={e=>setForm({...form,direction:e.target.value})}>{directions.map(d=><option key={d.id}>{d.name}</option>)}</select></label><label className="field-label">Название<input className="field-control" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label className="field-label">Описание<textarea className="field-control" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><label className="field-label">Pricing mode<select className="field-control" value={form.priceMode} onChange={e=>setForm({...form,priceMode:e.target.value as Tour['priceMode']})}><option value="fixed">fixed</option><option value="from-price">from-price</option><option value="dynamic-request">dynamic-request</option></select></label><label className="field-label">Adult price, $<input className="field-control" type="number" value={form.adult} onChange={e=>setForm({...form,adult:e.target.value})}/></label><label className="field-label">Schedule mode<select className="field-control" value={form.scheduleMode} onChange={e=>setForm({...form,scheduleMode:e.target.value as Tour['scheduleMode']})}><option value="demoDates">demoDates</option><option value="request">request</option></select></label><label className="field-label">Image URL<input className="field-control" value={form.image} onChange={e=>setForm({...form,image:e.target.value})}/></label><label className="checkbox"><input type="checkbox" checked={form.published} onChange={e=>setForm({...form,published:e.target.checked})}/> Опубликовать</label></div><ErrorBox error={error}/><button className="btn accent section" onClick={save}>Сохранить экскурсию</button></>}

function AdminSchedulePage(){const {items}=useTours(true);const {bump}=useApp();const [tourId,setTourId]=useState('dalat-premium');const [dates,setDates]=useState<AvailabilityDate[]>([]);const [date,setDate]=useState('2026-09-20');const [status,setStatus]=useState<AvailabilityDate['status']>('available');const [promo,setPromoState]=useState({enabled:false,label:'',value:''});const [message,setMessage]=useState('');useEffect(()=>{if(!items.some(t=>t.id===tourId)&&items[0])setTourId(items[0].id)},[items,tourId]);useEffect(()=>{if(tourId){api.availability(tourId).then(r=>setDates(r.items));const t=items.find(x=>x.id===tourId);setPromoState(t?.promo?{enabled:t.promo.enabled,label:t.promo.label,value:t.promo.value}:{enabled:false,label:'',value:''})}},[tourId,items]);const saveDate=async()=>{await api.schedule(tourId,{date,status});const r=await api.availability(tourId);setDates(r.items);bump();setMessage('DEMO availability сохранена в D1 и уже видна туристу.')};const savePromo=async()=>{await api.promo(tourId,promo);bump();setMessage('DEMO PROMO сохранена и отражается в каталоге/карточке тура.')};return <><div className="eyebrow">A04</div><h1>Расписание и акции</h1><label className="field-label">Тур<select className="field-control" value={tourId} onChange={e=>setTourId(e.target.value)}>{items.map(t=><option value={t.id} key={t.id}>{t.title}</option>)}</select></label><div className="grid two section"><div className="card"><h3>DEMO AVAILABILITY</h3>{dates.map(d=><InfoLine key={d.date} label={d.date} value={d.label}/>)}<label className="field-label section-sm">Дата<input className="field-control" type="date" value={date} onChange={e=>setDate(e.target.value)}/></label><label className="field-label">Статус<select className="field-control" value={status} onChange={e=>setStatus(e.target.value as AvailabilityDate['status'])}><option value="available">доступно</option><option value="low">мало мест</option><option value="request">по запросу</option></select></label><button className="btn secondary" onClick={saveDate}>Добавить / изменить</button></div><div className="card"><h3>DEMO PROMO</h3><label className="checkbox"><input type="checkbox" checked={promo.enabled} onChange={e=>setPromoState({...promo,enabled:e.target.checked})}/> Включить акцию</label><label className="field-label section-sm">Label<input className="field-control" value={promo.label} onChange={e=>setPromoState({...promo,label:e.target.value})}/></label><label className="field-label">Value<input className="field-control" value={promo.value} onChange={e=>setPromoState({...promo,value:e.target.value})}/></label><button className="btn secondary" onClick={savePromo}>Сохранить DEMO PROMO</button><p className="caption">По умолчанию promo OFF. Это не текущая акция MAX TOUR.</p></div></div>{message&&<div className="notice success section-sm">{message}</div>}</>}

function AdminAnalyticsPage(){
  const {items}=useTours(true);const [source,setSource]=useState('Все');const [tourId,setTourId]=useState('Все');const [direction,setDirection]=useState('Все');const [period,setPeriod]=useState('30');const [data,setData]=useState<AnalyticsResponse|null>(null);const [error,setError]=useState('');
  const directions=['Все',...Array.from(new Set(items.map(t=>t.direction)))];
  useEffect(()=>{const p=new URLSearchParams();p.set('source',source);p.set('tourId',tourId);p.set('direction',direction);p.set('period',period);api.analytics(p).then(setData).catch(e=>setError(e.message))},[source,tourId,direction,period]);
  return <><div className="section-head"><div><div className="eyebrow">A05</div><h1>Аналитика</h1></div><DemoBadge/></div><div className="grid four"><label className="field-label">Период<select className="field-control" value={period} onChange={e=>setPeriod(e.target.value)}><option value="7">7 дней</option><option value="30">30 дней</option><option value="90">90 дней</option></select></label><label className="field-label">Направление<select className="field-control" value={direction} onChange={e=>setDirection(e.target.value)}>{directions.map(x=><option key={x}>{x}</option>)}</select></label><label className="field-label">Канал<select className="field-control" value={source} onChange={e=>setSource(e.target.value)}>{['Все','Telegram','Сайт','Реклама','Другие каналы'].map(x=><option key={x}>{x}</option>)}</select></label><label className="field-label">Экскурсия<select className="field-control" value={tourId} onChange={e=>setTourId(e.target.value)}><option>Все</option>{items.filter(t=>direction==='Все'||t.direction===direction).map(t=><option value={t.id} key={t.id}>{t.title}</option>)}</select></label></div><ErrorBox error={error}/>{data?<><div className="kpi-grid section">{[['Просмотры',data.metrics.views],['Начали',data.metrics.started],['Заказы',data.metrics.orders],['Оплаты',data.metrics.paid],['Revenue demo',formatUsd(data.metrics.revenueMinor)],['Conversion demo',`${(data.metrics.conversion*100).toFixed(1)}%`],['Average order demo',formatUsd(data.metrics.averageOrderMinor)]].map(([label,value])=><div className="kpi" key={String(label)}><b>{value}</b><span>{label}</span></div>)}</div><section className="section"><h2>Источники</h2><div className="card bars">{data.sources.length?data.sources.map(s=><Bar key={s.source} label={s.source} value={s.orders} max={Math.max(1,...data.sources.map(x=>x.orders))}/>):<div className="empty">Нет данных по фильтрам</div>}</div></section><section className="section"><h2>Выбранные экскурсии</h2><div className="card bars">{data.tours.length?data.tours.map(t=><Bar key={t.tourId} label={t.title} value={t.orders} max={Math.max(1,...data.tours.map(x=>x.orders))}/>):<div className="empty">Нет данных по фильтрам</div>}</div></section><section className="section"><h2>Funnel</h2><div className="grid four">{data.funnel.map(x=><div className="kpi" key={x.stage}><b>{x.value}</b><span>{x.stage}</span></div>)}</div></section><section className="section"><h2>source → tour → order → payment</h2><div className="table-wrap"><table><thead><tr><th>Source</th><th>Tour</th><th>Order</th><th>Payment</th><th>Amount</th></tr></thead><tbody>{data.orders.map((r,i)=><tr key={i}><td>{r.source}</td><td>{r.tour}</td><td>{r.orderStatus}</td><td>{r.paymentStatus}</td><td>{formatUsd(r.amountMinor)}</td></tr>)}</tbody></table></div></section><div className="notice demo section">Все числа — DEMO ANALYTICS, а не реальные исторические показатели MAX TOUR или VIIVERSION.</div></>:<div className="card section">Загружаем аналитику…</div>}</>}

function AdminDirectionsPage(){const {bump}=useApp();const [items,setItems]=useState<Destination[]>([]);const [name,setName]=useState('');const [message,setMessage]=useState('');const load=()=>api.directions().then(r=>setItems(r.items));useEffect(()=>{load()},[]);const add=async()=>{if(!name.trim())return;await api.addDirection(name.trim());setName('');setMessage('DEMO направление сохранено в D1 текущей сессии.');bump();load()};return <><div className="eyebrow">A06</div><h1>Направления и масштабирование</h1><div className="grid two">{items.map(d=><div className="card" key={d.id}><span className="tag">{d.dataStatus==='userCreatedDemo'?'DEMO':'verifiedSite'}</span><h3>{d.name}</h3></div>)}</div><section className="card section"><h3>Добавить направление</h3><input className="field-control" value={name} onChange={e=>setName(e.target.value)} placeholder="DEMO новое направление"/><button className="btn accent section-sm" onClick={add}>Добавить направление</button>{message&&<div className="notice success section-sm">{message}</div>}</section></>}

function InfoLine({label,value}:{label:string;value:React.ReactNode}){return <div className="info-line"><span>{label}</span><b>{value}</b></div>}
function Bar({label,value,max}:{label:string;value:number;max:number}){return <div className="bar-row"><span>{label}</span><div className="bar"><i style={{width:`${Math.max(3,value/max*100)}%`}}/></div><b>{value}</b></div>}
function lines(text:string){return text.split('\n').map(x=>x.trim()).filter(Boolean)}
